select IFNULL(p.promoter_name,'无')as promoter_name,a.* from payment_estimate_apply a left JOIN promoted_info p on a.user_id = p.customer_id
where 1= 1 and delete_flag != 1

   and user_name = #{userName,jdbcType=VARCHAR}

order by create_time desc
limit #{pageIndex}, #{pageSize}

