select

from payment_estimate_apply
where  case_no = #{caseNo,jdbcType=VARCHAR}

    and user_name like  CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')


    and user_phone like  CONCAT(CONCAT('%',#{userPhone,jdbcType=VARCHAR}), '%')

